HUB=L('for-agencies-banned-client-accounts','agency hub')
DIR=L('meta-appeal-links-and-forms-directory','Meta appeal links directory')
REL=lambda x='':(x+', ' if x else '')+DIR+', '+HUB+', '+L('white-label-account-recovery','white-label account recovery')+'.'
SEND=lambda extra='':'<h2 id="what-to-send-us">What to send us</h2><p>Message us on <a href="https://wa.me/19342012490">WhatsApp</a> or email <a href="mailto:team@unbanz.com">team@unbanz.com</a> with:</p><ul><li>The account link or username, and which platform it is on.</li><li>A screenshot of the exact notice, with the date.</li><li>Whether an appeal was already submitted, and what happened.</li>'+extra+'<li>Never your password or login codes.</li></ul>'
AG='<li>Who holds admin access: the client, your agency, or both.</li><li>The Business Portfolio ID or ad account ID, if ads are involved.</li>'
W=('Meta Business Help','https://www.facebook.com/business/help','Help for Pages, admins, Business Portfolio and ads.')
PG=('Page Quality / Business Support Home','https://business.facebook.com/accountquality','Shows restrictions on Pages, ad accounts and Business Portfolios, with a request review option.')
def q(slug,title,crumb,desc,h1,lede,ans,cards,pre,secs,post,rel,faqs): return mk(slug,title,crumb,desc,h1,lede,ans,cards,pre,secs,post,rel,faqs)
PAGES=[
q('for-agencies-banned-client-accounts','For Agencies: Client Instagram, Facebook and Ad Accounts Banned or Disabled','For agencies',
 'A hub for marketing agencies, SMMA owners and white-label resellers whose client Instagram, Facebook, Business Portfolio or ad accounts were disabled, restricted or hacked.',
 'Your client’s account got banned. Start here.','For agencies, SMMA owners, freelancers and white-label resellers handling disabled, restricted or hacked client accounts.',
 '<strong>When a client account is disabled, find out which asset is affected and who holds admin access.</strong> A personal profile is appealed by its owner from the login notice. Pages, ad accounts and Business Portfolios are reviewed in Business Support Home by an admin. Agencies can work with Unbanz directly or white-label: you keep the client relationship, we work on the recovery under your brand. Meta makes the final decision.',
 [('Which asset','Profile, Page, ad account or portfolio.'),('Who is admin','Client, agency, or both.'),('White-label','Your brand, our recovery work.')],
 '<h2 id="questions">Questions agencies ask</h2><ul><li>'+L('my-clients-instagram-got-disabled-what-do-i-do-as-their-agency','My client’s Instagram got disabled. What do I do as their agency?')+'</li><li>'+L('client-ad-account-restricted-agency-is-admin','Client’s ad account restricted and the agency is admin')+'</li><li>'+L('agency-business-portfolio-disabled-all-client-ad-accounts-down','Agency Business Portfolio disabled, all client ad accounts down')+'</li><li>'+L('agency-business-manager-restricted-after-adding-a-client','Business Manager restricted after adding a client')+'</li><li>'+L('smma-owner-profile-disabled-lost-access-to-client-pages','SMMA owner profile disabled, lost all client Pages')+'</li><li>'+L('franchise-multi-location-facebook-pages-disabled','Franchise or multi-location Pages disabled')+'</li><li>'+L('questions-agencies-ask-about-banned-client-accounts','All questions agencies ask')+'</li></ul><h2 id="industries">By client industry</h2><ul><li>'+L('restaurant-instagram-or-facebook-page-disabled','Restaurants')+'</li><li>'+L('salon-barber-instagram-or-facebook-disabled','Salons and barbers')+'</li><li>'+L('dental-or-medical-clinic-facebook-instagram-disabled','Dental and medical clinics')+'</li><li>'+L('real-estate-agent-facebook-instagram-disabled','Real estate agents')+'</li><li>'+L('gym-fitness-studio-instagram-facebook-disabled','Gyms and studios')+'</li><li>'+L('ecommerce-store-instagram-facebook-disabled','Ecommerce stores')+'</li><li>'+L('contractor-home-services-facebook-page-disabled','Contractors and home services')+'</li><li>'+L('law-firm-facebook-instagram-disabled','Law firms')+'</li></ul>',
 [('links','Official links for business assets',[PG,ADS[0],ADS[1],FB[0],IG[1],W])],
 ['<h2 id="white-label">White-label for agencies</h2><p>Refer client accounts and keep your brand in front. See '+L('how-white-label-account-recovery-works','how white-label recovery works')+', '+L('become-a-white-label-recovery-partner','become a partner')+', '+L('what-your-client-sees-white-label-recovery','what your client sees')+' and '+L('agency-intake-form-checklist-account-recovery','the intake checklist')+'.</p>',SEND(AG)],
 DIR+', '+L('white-label-agency','white-label agency')+', '+L('white-label-agency-faq','white-label FAQ')+'.',
 [('Can an agency appeal on behalf of a client?','For Pages, ad accounts and Business Portfolios, an admin can request a review in Business Support Home. A disabled personal profile is appealed by its owner.'),('Can we keep Unbanz invisible to our client?','Yes. In a white-label setup you speak to the client and we work behind your brand.'),('Does Unbanz need the client’s password?','No. Never share passwords or login codes.')]),
q('my-clients-instagram-got-disabled-what-do-i-do-as-their-agency','My Client’s Instagram Got Disabled. What Do I Do as Their Agency?','Client Instagram disabled',
 'Your client’s Instagram account was disabled or suspended and you manage it as their agency. Who can appeal, what to tell the client, and the first steps.',
 'My client’s Instagram got disabled. What do I do as their agency?','You manage the account, but the appeal usually has to come from the account itself.',
 '<strong>The appeal is submitted from the notice shown when someone logs in to the disabled account.</strong> If your agency logs in with the client’s permission, you can see it; otherwise the client does it. Screenshot the notice, check whether it says suspended, disabled or hacked, appeal once with a short factual message, and stop all posting tools and logins from new devices. Meta makes the final decision.',
 [('Notice first','Screenshot it with the date.'),('One appeal','Short and factual.'),('Pause tools','Scheduling apps and new logins.')],
 '<h2 id="steps">Steps for the agency</h2><ol><li>Ask the client for a screenshot of the notice if you cannot log in.</li><li>Agree who submits the appeal, and use the device the account normally uses.</li><li>Disconnect third-party scheduling or growth apps.</li><li>Do not create a replacement account for the client yet.</li><li>Tell the client what happened and what the next step is, without promising a date.</li></ol>',
 [('links','Official links',IG[:4])],[SEND(AG)],REL(L('instagram-appeal-links-and-forms-directory','Instagram appeal links')),
 [('Can my agency appeal from our own account?','No. The appeal comes from the disabled account’s own notice.'),('Should we tell the client it will come back?','Avoid predictions. Meta makes the final decision.')]),
q('client-ad-account-restricted-agency-is-admin','Client’s Ad Account Restricted and the Agency Is Admin: What to Do','Client ad account restricted',
 'A client’s Meta ad account is restricted or disabled and your agency is an admin on it. Who should request the review, where, and what to check first.',
 'The client’s ad account is restricted and we are the admin. What now?','Agency admins can request a review, but the account owner’s setup also matters.',
 '<strong>An admin, agency or client, can request a review in Business Support Home on a computer.</strong> Open the restricted ad account, read the reason, check payment methods and recent ads, then use the request review option once. If the restriction is on a person rather than the ad account, that person appeals their own restriction first. Meta makes the final decision.',
 [('Business Support Home','On a computer, as admin.'),('Read the reason','Ads, payment, or person.'),('One request','Avoid repeated requests.')],
 '<h2 id="check">Check before requesting a review</h2><ul><li>Recent rejected ads and the policy named.</li><li>Failed or disputed payments.</li><li>A new admin, new payment method or new country of login just before the restriction.</li></ul><p>See also '+L('ad-account-restricted-after-agency-shared-access','restricted after agency shared access')+' and '+L('client-ad-account-disabled-agency-help','client ad account disabled')+'.</p>',
 [('links','Official links',[PG,ADS[0],ADS[1],ADS[4]])],[SEND(AG)],REL(L('meta-ad-account-appeal-links-directory','Meta ad account appeal links')),
 [('Should the client or the agency request the review?','Either can as an admin. The one who best knows the account history should write it.')]),
q('agency-business-portfolio-disabled-all-client-ad-accounts-down','Agency Business Portfolio Disabled, All Client Ad Accounts Down','Agency portfolio disabled',
 'Your agency’s Meta Business Portfolio was disabled and every client ad account in it stopped. What to do for the portfolio, the clients, and the next campaigns.',
 'Our agency Business Portfolio was disabled and all client ad accounts are down.','One restriction on the agency portfolio can stop every client at once.',
 '<strong>Request a review of the Business Portfolio in Business Support Home, and check whether an admin’s personal profile is also restricted.</strong> Ad accounts owned by clients can often be reconnected to the client’s own portfolio, while accounts owned by your agency portfolio stay blocked until it is reviewed. Do not create new portfolios to get around the restriction. Meta makes the final decision.',
 [('Portfolio review','Business Support Home.'),('Owned vs shared','Client-owned accounts are separate.'),('No new portfolios','They can be restricted too.')],
 '<h2 id="clients">Keeping clients running</h2><ul><li>List which ad accounts your portfolio owns and which are shared from clients.</li><li>Client-owned accounts: the client can remove your portfolio as partner and keep running ads themselves.</li><li>Tell clients honestly what is affected.</li></ul><p>More: '+L('agency-business-portfolio-restricted-client-accounts','restricted client accounts')+', '+L('meta-business-portfolio-disabled-all-ad-accounts-lost','all ad accounts lost')+'.</p>',
 [('links','Official links',BP)],[SEND(AG)],REL(L('meta-business-portfolio-appeal-links-directory','Business Portfolio appeal links')),
 [('Can clients move their ad accounts away?','Ad accounts owned by the client’s own portfolio can keep running without your agency. Accounts owned by your portfolio cannot be transferred out while restricted.')]),
q('agency-business-manager-restricted-after-adding-a-client','Agency Business Manager Restricted After Adding a Client','Restricted after adding a client',
 'Your agency Business Manager (Business Portfolio) was restricted right after you added a new client’s Page or ad account. Why it happens and what to do.',
 'Our Business Manager got restricted after adding a client.','Adding a client asset that already had problems can affect the portfolio it joins.',
 '<strong>Check the new client’s assets first.</strong> If the Page, ad account or admin you added already had a restriction, policy history or a recent hack, Meta may link that history to your portfolio. Request a review in Business Support Home, and consider removing the new asset after speaking with the client. Meta makes the final decision.',
 [('Check the asset','Past restrictions carry over.'),('Talk to the client','Before removing anything.'),('Review','Business Support Home.')],
 '<h2 id="prevent">Before adding the next client</h2><ul><li>Ask the client for a screenshot of their Account Quality page.</li><li>Ask about past ad rejections and hacks.</li><li>Use partner access to the client’s own portfolio instead of moving assets into yours.</li></ul><p>See '+L('agency-onboarding-checklist-white-label-partner','onboarding checklist')+' and '+L('prevent-client-account-lockouts-agency-checklist','preventing client lockouts')+'.</p>',
 [('links','Official links',BP[:4])],[SEND(AG)],REL(),
 [('Should agencies own client ad accounts?','Many agencies prefer partner access to client-owned assets, so a restriction on one side does not take everything down.')]),
q('smma-owner-profile-disabled-lost-access-to-client-pages','SMMA Owner: Personal Facebook Disabled, Lost Access to All Client Pages','SMMA profile disabled',
 'Your personal Facebook profile was disabled and it was the admin on every client Page and ad account. What to do first and how clients can keep running.',
 'My personal profile got disabled and I lost every client Page.','Pages and ad accounts are managed through people. When the person is disabled, access goes with it.',
 '<strong>Appeal your personal profile from its notice, and ask each client to check their own admin access.</strong> If a client still has full control of their Page or portfolio, they can keep running and later add you back. If you were the only admin, the assets wait on your profile appeal. Do not open a second profile. Meta makes the final decision.',
 [('Profile appeal','It unlocks your access.'),('Client admins','Clients with full control keep running.'),('No second profile','It can be linked and disabled.')],
 '<h2 id="after">After you are back</h2><ul><li>Make sure every client holds full control of their own assets.</li><li>Add a second trusted admin from your team.</li><li>Turn on two-factor authentication everywhere.</li></ul>',
 [('links','Official links',[FB[0],FB[1],PG,W])],[SEND(AG)],REL(L('facebook-business-owner-profile-suspended','business owner profile suspended')),
 [('Can a client remove me while I am disabled?','A client with full control can manage people on their own assets.')]),
]
def local(slug,biz,title,triggers,extra,rel):
    return q(slug,title,biz.capitalize(),f'Your {biz} Instagram account or Facebook Page was disabled or restricted. Common triggers for {biz}s, the official routes, and what to do next.',
     title+'. What now?',f'What usually triggers it for {biz}s, and what to do first.',
     f'<strong>Find out whether the Page, the Instagram account, or the owner’s personal profile is affected.</strong> A disabled Instagram account or personal profile is appealed from the notice at login. A restricted Page is reviewed in Business Support Home by an admin. Common triggers for {biz}s are listed below. Meta makes the final decision.',
     [('Which asset','Page, Instagram or profile.'),('Triggers','Industry-specific flags.'),('Appeal once','Short and factual.')],
     '<h2 id="triggers">Common triggers for '+biz+'s</h2><ul>'+''.join(f'<li>{t}</li>' for t in triggers)+'</ul>'+extra,
     [('links','Official links',[IG[1],IG[0],FB[0],PG,FB[1]])],[STEPS,SEND('<li>The business name and website.</li>')],REL(rel),
     [(f'Can my {biz} keep taking bookings meanwhile?','Yes. Point customers to your website, phone, Google listing or WhatsApp while the account is under appeal.'),('Should I make a new account?','Not while an appeal is open. New accounts from the same device or phone can be linked.'),('Does Unbanz need my password?','No. Never share passwords or login codes.')])
